begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000005801','recovery@test.local'),('00000000-0000-4000-8000-000000005802','recovery-other@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000005801','Recovery','00000000-0000-4000-8000-000000005801'),('10000000-0000-4000-8000-000000005802','Other','00000000-0000-4000-8000-000000005802');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801'),('10000000-0000-4000-8000-000000005802','00000000-0000-4000-8000-000000005802');
update public.ai_operation_policies set per_minute=20 where action='generate';
insert into public.learning_credit_grants(family_id,kind,amount,ends_at,reason) values('10000000-0000-4000-8000-000000005801','ai_questions',20,now()+interval '1 day','Synthetic test');
create function pg_temp.intent() returns jsonb language sql as $$select '{"subject":"Fen","grade":5,"count":1}'::jsonb$$;
create function pg_temp.context() returns jsonb language sql as $$select jsonb_build_object('schema','gina.generation-context.v1','promptHash',repeat('a',64),'total',1,'catalogueBound',false,'subject','Fen','grade',5,'model','original-model')$$;
create function pg_temp.reserve(p uuid,ctx jsonb default pg_temp.context()) returns jsonb language sql as $$select public.reserve_prova_generation_v3(p,'10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',repeat('a',64),1,pg_temp.intent(),ctx)$$;
create function pg_temp.resume(p uuid,intent jsonb default pg_temp.intent()) returns jsonb language sql as $$select public.resume_prova_generation(p,'10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',intent)$$;
set local role authenticated;select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000005801","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005801"}}',true);
select throws_ok($$select pg_temp.reserve(gen_random_uuid())$$,'42501',null,'parent cannot reserve provider work directly');
select throws_ok($$select * from gina.prova_generation_contexts$$,'42501',null,'model prompt context private');
select throws_ok($$select public.cancel_unstarted_generation(gen_random_uuid(),null)$$,'P0001','invalid_input','null intent rejected');
select is(public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005801',pg_temp.intent())->>'status','cancelled','unstarted request fenced');
select is(public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005801',pg_temp.intent())->>'status','cancelled','lost cancellation reply replayable');
select throws_ok($$select public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005801','{}')$$,'P0001','request_conflict','cancellation intent immutable');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(pg_temp.resume(gen_random_uuid()),null::jsonb,'checking unknown request does not reserve or charge');
select is(pg_temp.reserve('20000000-0000-4000-8000-000000005801')->>'error','generation_cancelled','late request cannot start after cancellation');
select throws_ok($$select public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000005801','10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',repeat('a',64),1)$$,'P0001','generation_cancelled','old service endpoint also respects cancellation');
select throws_ok($$select public.resume_prova_generation('20000000-0000-4000-8000-000000005801','10000000-0000-4000-8000-000000005802','00000000-0000-4000-8000-000000005802',pg_temp.intent())$$,'42501','forbidden','foreign cancellation not disclosed');
select throws_ok($$select pg_temp.reserve(gen_random_uuid(),pg_temp.context()-'catalogueBound')$$,'P0001','invalid_generation_context','missing context tag rejected');
select ok(pg_temp.reserve('20000000-0000-4000-8000-000000005802')?'lease','fresh intent stores context atomically with reservation');
select is(pg_temp.reserve('20000000-0000-4000-8000-000000005802')->>'error','generation_in_progress','repeat does not start a second paid call');
select is(pg_temp.resume('20000000-0000-4000-8000-000000005802','{}')->>'error','request_conflict','changed replay rejected');
select throws_ok($$select public.resume_prova_generation('20000000-0000-4000-8000-000000005802','10000000-0000-4000-8000-000000005802','00000000-0000-4000-8000-000000005802',pg_temp.intent())$$,'42501','forbidden','foreign result denied');
set local role authenticated;select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000005801","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005801"}}',true);
select throws_ok($$select public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005802',pg_temp.intent())$$,'P0001','generation_cannot_cancel','working request cannot be discarded');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.save_prova_provider_result('20000000-0000-4000-8000-000000005802',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000005802'),'{"output":{"questions":[]}}');
select is(pg_temp.resume('20000000-0000-4000-8000-000000005802')->'context',pg_temp.context(),'original finishing context survives lost reply');
select is(pg_temp.reserve('20000000-0000-4000-8000-000000005802',pg_temp.context()||'{"model":"changed-model"}')->'context',pg_temp.context(),'concurrent new config cannot overwrite original context');
select ok(pg_temp.resume('20000000-0000-4000-8000-000000005802')?'provider_result','saved provider output recovered without provider call');
select public.complete_prova_generation_v2('20000000-0000-4000-8000-000000005802',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000005802'),'[{"grade":5,"subject":"Fen","topic":"Isı","kind":"open_ended","difficulty":"orta","stem":"Isı nedir?","expected_answer":"Enerji aktarımı","solution":"Açıklama","source_urls":[],"provenance":{}}]','original-model','v1',10,20);
reset role;
insert into public.app_settings(key,value) values('ai.enabled','false') on conflict (key) do update set value=excluded.value;update public.plans set prova_ai_generate_monthly=0;
set local role service_role;
select ok(pg_temp.resume('20000000-0000-4000-8000-000000005802')?'cached','completed result available with AI disabled');
select is((select sum(consumed)::int from public.generation_credit_allocations),1,'recovery never consumes twice');
select is((select count(*)::int from public.prova_ai_usage),1,'one usage record');
select ok(pg_temp.reserve('20000000-0000-4000-8000-000000005803')?'lease','second synthetic work reserves');
select public.fail_prova_generation_v2('20000000-0000-4000-8000-000000005803',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000005803'),'anthropic_429',false);
select is(pg_temp.resume('20000000-0000-4000-8000-000000005803')->>'error','generation_failed_safe','definite failure distinct from uncertain outcome');
select is(pg_temp.reserve('20000000-0000-4000-8000-000000005803')->>'error','generation_failed_safe','failed paid intent not silently restarted');
set local role authenticated;select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000005801","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005801"}}',true);
select is(public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005803',pg_temp.intent())->>'status','cancelled','definite failure closed with fence');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(pg_temp.reserve('20000000-0000-4000-8000-000000005803')->>'error','generation_cancelled','fenced failed request never restarts');
select ok(pg_temp.reserve('20000000-0000-4000-8000-000000005804')?'lease','third synthetic work reserves');
select public.fail_prova_generation_v2('20000000-0000-4000-8000-000000005804',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000005804'),'provider_outcome_unknown',true);
select is(pg_temp.resume('20000000-0000-4000-8000-000000005804')->>'error','ai_result_uncertain','uncertain response cannot be paid again');
set local role authenticated;select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000005801","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000005801"}}',true);
select throws_ok($$select public.cancel_unstarted_generation('20000000-0000-4000-8000-000000005804',pg_temp.intent())$$,'P0001','generation_cannot_cancel','uncertain provider work cannot be silently abandoned');
reset role;
insert into public.prova_generation_jobs(id,family_id,requested_by,prompt_hash,items,status) values('20000000-0000-4000-8000-000000005805','10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',repeat('b',64),1,'failed');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(pg_temp.resume('20000000-0000-4000-8000-000000005805')->>'error','generation_legacy_request','legacy intent not guessed or automatically regenerated');
reset role;
insert into public.children(id,family_id,name,grade) values('30000000-0000-4000-8000-000000005801','10000000-0000-4000-8000-000000005801','Synthetic child',5);
insert into public.prova_drafts(id,family_id,created_by,version,content) values('40000000-0000-4000-8000-000000005801','10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',2,'{"childId":"30000000-0000-4000-8000-000000005801","grade":5,"subjects":["Fen"],"purpose":"written"}');
create function pg_temp.reserve_draft(v int) returns jsonb language sql as $$select public.reserve_prova_generation_v3('20000000-0000-4000-8000-000000005806','10000000-0000-4000-8000-000000005801','00000000-0000-4000-8000-000000005801',repeat('a',64),1,pg_temp.intent()||'{"draft_id":"40000000-0000-4000-8000-000000005801"}',pg_temp.context()||jsonb_build_object('draftScope',jsonb_build_object('id','40000000-0000-4000-8000-000000005801','version',v)))$$;
set local role service_role;
select throws_ok($$select pg_temp.reserve_draft(1)$$,'P0001','prova_draft_changed','draft changed during preparation cannot incur charge');
reset role;update public.children set grade=6;set local role service_role;
select throws_ok($$select pg_temp.reserve_draft(2)$$,'P0001','prova_draft_changed','live child grade checked again at reservation');
reset role;update public.children set grade=5;set local role service_role;
select ok(pg_temp.reserve_draft(2)?'lease','current child/draft scope reserves with frozen context');
reset role;
select is((select count(*)::int from gina.prova_generation_contexts),4,'only actual new reservations get context');
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000005801';set constraints all immediate;$$,'private recovery records do not block account deletion');
select * from finish();rollback;
